policies.inbound:




    {{driftline-api-app-id}}
    {{driftline-api-audience}}


    https://login.microsoftonline.com/{{tenant-id}}/v2.0
    https://sts.windows.net/{{tenant-id}}/





<set-variable name="rpc" value="@{
  if (context.Request.Method != "POST") { return "{}"; }
  var body = context.Request.Body?.As(preserveContent: true);
  return body == null ? "{}" : body.ToString(Newtonsoft.Json.Formatting.None);
}" />

<set-variable name="verdict" value="@{
  var tool = (string)context.Variables["tool"];
  if (tool == "none") { return "allow"; }
  var rpc = JObject.Parse((string)context.Variables["rpc"]);
  var args = rpc["params"]?["arguments"] as JObject ?? new JObject();
  var roles = ((string)context.Variables["roles"]).Split(',').Select(r => r.Trim()).ToArray();

  var never = new [] { "merge_pull_request", "update_pull_request_branch", "delete_file",
    "delete_repository", "create_repository", "fork_repository", "pull_request_review_write",
    "update_branch_protection", "delete_branch" };
  if (never.Contains(tool)) { return "deny:" + tool + " is never allowed"; }

  // Fault definitions, eval answers and design docs would hand agents the answer, so no
  // agent may read them (ADR 0007). Code search is not offered for the same reason.
  var hidden = new [] { "apps/patient-rag/faults", "evals", "synth", "data", "docs", "scripts" };
  var readPath = (((string)args["path"]) ?? "").TrimStart('/');
  if (tool == "get_file_contents" && (readPath.Contains("..") ||
      hidden.Any(h => readPath == h || readPath.StartsWith(h + "/")))) {
    return "deny:reading " + readPath + " is not allowed";
  }

  var branch = (string)args["branch"] ?? "";
  var writes = new [] { "create_or_update_file", "push_files" };
  if (writes.Contains(tool) && (branch == "main" || branch == "refs/heads/main" || branch == "")) {
    return "deny:writes to main are not allowed";
  }
  if (tool == "create_branch" && !branch.StartsWith("driftline/")) {
    return "deny:branches must be named driftline/*";
  }
  if (tool == "create_pull_request" && !(((string)args["head"] ?? "").StartsWith("driftline/"))) {
    return "deny:pull requests must come from driftline/* branches";
  }
  var allowedPrefixes = new [] { "apps/patient-rag/config/", "apps/patient-rag/prompts/" };
  var paths = new System.Collections.Generic.List();
  if (tool == "create_or_update_file") { paths.Add((string)args["path"] ?? ""); }
  if (tool == "push_files" && args["files"] is JArray files) {
    foreach (var f in files) { paths.Add((string)f["path"] ?? ""); }
  }
  foreach (var p in paths) {
    if (p.Contains("..") || !allowedPrefixes.Any(a => p.StartsWith(a))) {
      return "deny:write outside the allowlist: " + p;
    }
  }

  var read = new [] { "get_file_contents", "list_commits", "get_commit", "list_branches",
    "list_pull_requests", "pull_request_read", "search_pull_requests" };
  var prWriter = read.Concat(new [] { "create_branch", "create_or_update_file", "push_files",
    "create_pull_request", "update_pull_request" }).ToArray();
  var allow = new System.Collections.Generic.Dictionary {
    { "agent.retrieval", read }, { "agent.prompt", read }, { "agent.index", read },
    { "agent.performance", read }, { "agent.validator", read }, { "agent.explainer", read },
    { "agent.prwriter", prWriter }
  };
  if (roles.Any(r => allow.ContainsKey(r) && allow[r].Contains(tool))) { return "allow"; }
  return "deny:" + tool + " is not in the allowlist for roles [" + string.Join(",", roles) + "]";
}" />

  @("github-mcp " + (string)context.Variables["tool"] + " -> " + (string)context.Variables["verdict"])









      application/json
      apim
      @{
        var rpc = JObject.Parse((string)context.Variables["rpc"]);
        return new JObject(
          new JProperty("jsonrpc", "2.0"),
          new JProperty("id", rpc["id"]),
          new JProperty("error", new JObject(
            new JProperty("code", -32003),
            new JProperty("message", "Forbidden by Driftline gateway policy: " + ((string)context.Variables["verdict"]).Substring(5))))
        ).ToString();
      }






  @("Bearer " + (string)context.Variables["backendToken"])


  @((string)context.Variables["caller"])
